package com.google.javascript.rhino;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TokenStream_isKeyword_TriageGen1Test {

    @Test
    public void testIsKeyword_TwoChars() {
        assertTrue("if", TokenStream.isKeyword("if"));
        assertTrue("in", TokenStream.isKeyword("in"));
        assertTrue("do", TokenStream.isKeyword("do"));
        assertFalse("ia", TokenStream.isKeyword("ia"));
        assertFalse("ifx", TokenStream.isKeyword("ifx")); // Length 3, but logic handles length 2 first
        assertFalse("id", TokenStream.isKeyword("id"));
        assertFalse("io", TokenStream.isKeyword("io"));
    }

    @Test
    public void testIsKeyword_ThreeChars() {
        assertTrue("for", TokenStream.isKeyword("for"));
        assertTrue("int", TokenStream.isKeyword("int"));
        assertTrue("new", TokenStream.isKeyword("new"));
        assertTrue("try", TokenStream.isKeyword("try"));
        assertTrue("var", TokenStream.isKeyword("var"));
        assertFalse("forx", TokenStream.isKeyword("forx"));
        assertFalse("fon", TokenStream.isKeyword("fon"));
        assertFalse("fof", TokenStream.isKeyword("fof"));
        assertFalse("itx", TokenStream.isKeyword("itx"));
        assertFalse("inw", TokenStream.isKeyword("inw"));
        assertFalse("nwe", TokenStream.isKeyword("nwe"));
        assertFalse("tew", TokenStream.isKeyword("tew"));
        assertFalse("vax", TokenStream.isKeyword("vax"));
    }

    @Test
    public void testIsKeyword_FourChars() {
        assertTrue("byte", TokenStream.isKeyword("byte"));
        assertTrue("case", TokenStream.isKeyword("case"));
        assertTrue("char", TokenStream.isKeyword("char"));
        assertTrue("else", TokenStream.isKeyword("else"));
        assertTrue("enum", TokenStream.isKeyword("enum"));
        assertTrue("goto", TokenStream.isKeyword("goto"));
        assertTrue("long", TokenStream.isKeyword("long"));
        assertTrue("null", TokenStream.isKeyword("null"));
        assertTrue("true", TokenStream.isKeyword("true"));
        assertTrue("this", TokenStream.isKeyword("this"));
        assertTrue("void", TokenStream.isKeyword("void"));
        assertTrue("with", TokenStream.isKeyword("with"));

        // Partial match validation tests (X != null && X != s)
        assertFalse("casee", TokenStream.isKeyword("casee"));
        assertFalse("casr", TokenStream.isKeyword("casr"));
        assertFalse("casb", TokenStream.isKeyword("casb"));
        assertFalse("elsex", TokenStream.isKeyword("elsex"));
        assertFalse("elmu", TokenStream.isKeyword("elmu"));
        assertFalse("enun", TokenStream.isKeyword("enun"));
        assertFalse("truee", TokenStream.isKeyword("truee"));
        assertFalse("trus", TokenStream.isKeyword("trus"));
    }

    @Test
    public void testIsKeyword_FiveChars() {
        assertTrue("class", TokenStream.isKeyword("class"));
        assertTrue("break", TokenStream.isKeyword("break"));
        assertTrue("while", TokenStream.isKeyword("while"));
        assertTrue("false", TokenStream.isKeyword("false"));
        assertTrue("const", TokenStream.isKeyword("const"));
        assertTrue("final", TokenStream.isKeyword("final"));
        assertTrue("float", TokenStream.isKeyword("float"));
        assertTrue("short", TokenStream.isKeyword("short"));
        assertTrue("super", TokenStream.isKeyword("super"));
        assertTrue("throw", TokenStream.isKeyword("throw"));
        assertTrue("catch", TokenStream.isKeyword("catch"));
    }

    @Test
    public void testIsKeyword_SixChars() {
        assertTrue("native", TokenStream.isKeyword("native"));
        assertTrue("delete", TokenStream.isKeyword("delete"));
        assertTrue("return", TokenStream.isKeyword("return"));
        assertTrue("throws", TokenStream.isKeyword("throws"));
        assertTrue("import", TokenStream.isKeyword("import"));
        assertTrue("double", TokenStream.isKeyword("double"));
        assertTrue("static", TokenStream.isKeyword("static"));
        assertTrue("public", TokenStream.isKeyword("public"));
        assertTrue("switch", TokenStream.isKeyword("switch"));
        assertTrue("export", TokenStream.isKeyword("export"));
        assertTrue("typeof", TokenStream.isKeyword("typeof"));
    }

    @Test
    public void testIsKeyword_SevenChars() {
        assertTrue("package", TokenStream.isKeyword("package"));
        assertTrue("default", TokenStream.isKeyword("default"));
        assertTrue("finally", TokenStream.isKeyword("finally"));
        assertTrue("boolean", TokenStream.isKeyword("boolean"));
        assertTrue("private", TokenStream.isKeyword("private"));
        assertTrue("extends", TokenStream.isKeyword("extends"));
    }

    @Test
    public void testIsKeyword_EightChars() {
        assertTrue("abstract", TokenStream.isKeyword("abstract"));
        assertTrue("continue", TokenStream.isKeyword("continue"));
        assertTrue("debugger", TokenStream.isKeyword("debugger"));
        assertTrue("function", TokenStream.isKeyword("function"));
        assertTrue("volatile", TokenStream.isKeyword("volatile"));
    }

    @Test
    public void testIsKeyword_NineChars() {
        assertTrue("interface", TokenStream.isKeyword("interface"));
        assertTrue("protected", TokenStream.isKeyword("protected"));
        assertTrue("transient", TokenStream.isKeyword("transient"));
    }

    @Test
    public void testIsKeyword_TenChars() {
        assertTrue("implements", TokenStream.isKeyword("implements"));
        assertTrue("instanceof", TokenStream.isKeyword("instanceof"));
    }

    @Test
    public void testIsKeyword_TwelveChars() {
        assertTrue("synchronized", TokenStream.isKeyword("synchronized"));
    }

    @Test
    public void testIsKeyword_Other() {
        assertFalse("abc", TokenStream.isKeyword("abc"));
        assertFalse("a", TokenStream.isKeyword("a"));
        assertFalse("", TokenStream.isKeyword(""));
        assertFalse("longerthananything", TokenStream.isKeyword("longerthananything"));
    }
}
